package com.cognia.api.application.service;
import com.cognia.api.application.port.in.LearningPathUseCases; import com.cognia.api.application.port.out.*; import com.cognia.api.domain.model.*; import com.cognia.api.domain.service.*; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class LearningPathService implements LearningPathUseCases {
	private final LearningPathRepository paths; private final ShortEvaluationRepository evaluations; private final DiagnosticRepository diagnostics; private final StudentExistencePort students; private final SubjectRepository subjects; private final ConceptRepository concepts; private final PrerequisiteRepository prerequisites; private final ActivityRepository activities; private final ActivityCorrectionService correction; private final MasteryPolicy mastery; private final ReviewDeckPort reviewDeck; private final java.time.Clock clock; private final int initialReviewDelayDays; private final LearningPathGenerator generator=new LearningPathGenerator(); private final double initialThreshold,approvalThreshold; private final int failuresBeforeRecalculation;
	@org.springframework.beans.factory.annotation.Autowired
	public LearningPathService(LearningPathRepository paths,ShortEvaluationRepository evaluations,DiagnosticRepository diagnostics,StudentExistencePort students,SubjectRepository subjects,ConceptRepository concepts,PrerequisiteRepository prerequisites,ActivityRepository activities,ActivityCorrectionService correction,MasteryPolicy mastery,ReviewDeckPort reviewDeck,java.time.Clock clock,@Value("${review.initial-delay-days:1}") int initialReviewDelayDays,@Value("${learning-path.initial-mastery-threshold:0.8}") double initialThreshold,@Value("${learning-path.short-evaluation.approval-threshold:70}") double approvalThreshold,@Value("${learning-path.short-evaluation.consecutive-failures-before-recalculation:2}") int failuresBeforeRecalculation){this.paths=paths;this.evaluations=evaluations;this.diagnostics=diagnostics;this.students=students;this.subjects=subjects;this.concepts=concepts;this.prerequisites=prerequisites;this.activities=activities;this.correction=correction;this.mastery=mastery;this.reviewDeck=reviewDeck;this.clock=clock;if(initialReviewDelayDays<0)throw new IllegalArgumentException("Initial review delay cannot be negative");this.initialReviewDelayDays=initialReviewDelayDays;this.initialThreshold=initialThreshold;this.approvalThreshold=approvalThreshold;this.failuresBeforeRecalculation=failuresBeforeRecalculation;}
	public LearningPathService(LearningPathRepository paths,ShortEvaluationRepository evaluations,DiagnosticRepository diagnostics,StudentExistencePort students,SubjectRepository subjects,ConceptRepository concepts,PrerequisiteRepository prerequisites,ActivityRepository activities,ActivityCorrectionService correction,MasteryPolicy mastery,double initialThreshold,double approvalThreshold,int failuresBeforeRecalculation){this(paths,evaluations,diagnostics,students,subjects,concepts,prerequisites,activities,correction,mastery,new ReviewDeckPort(){public List<ReviewCard> activeCards(UUID id){return List.of();}public Optional<ReviewCard> card(UUID id){return Optional.empty();}public void addMissingProgress(UUID s,UUID c,List<ReviewCard> cards,java.time.Instant due){}public void resetConsecutiveLapses(UUID s,UUID c){}},java.time.Clock.systemUTC(),1,initialThreshold,approvalThreshold,failuresBeforeRecalculation);}
	public LearningPath generate(UUID student,UUID subject){checkStudent(student);if(subjects.findById(subject).isEmpty())throw new ResourceNotFoundException("Subject was not found");if(paths.active(student,subject).isPresent())throw new DiagnosticConflictException("An active learning path already exists");diagnostics.ensureProfile(student,subject);var profile=diagnostics.profile(student,subject);if(!profile.diagnosticCompleted())throw new DiagnosticConflictException("A completed diagnostic is required");return createPath(student,subject,profile,null);}
	public LearningPath get(UUID student,UUID subject){checkStudent(student);return paths.active(student,subject).or(()->paths.latest(student,subject)).orElseThrow(()->new ResourceNotFoundException("Learning path was not found"));}
	public Recommendation next(UUID student,UUID subject){var path=get(student,subject);var step=path.steps().stream().filter(s->s.state()==PathStep.State.EN_PROGRESO||s.state()==PathStep.State.REFUERZO).findFirst().or(()->path.steps().stream().filter(s->s.state()==PathStep.State.DISPONIBLE).findFirst()).orElseThrow(()->new ResourceNotFoundException("No eligible path step"));var masteryLevel=diagnostics.profile(student,subject).masteries().stream().filter(m->m.conceptId().equals(step.conceptId())).map(ConceptMastery::level).findFirst().orElse(0d);var recs=(step.state()==PathStep.State.REFUERZO?activities.findPracticeByConceptAtMost(step.conceptId(),evaluations.reinforcementDifficulty(student,step.id())):activities.findPracticeByConcept(step.conceptId(),null)).stream().filter(a->a.active()&&a.usage()==Activity.Usage.PRACTICA).map(a->new RecommendedActivity(a,"Concepto en "+step.state()+", dominio estimado "+String.format(Locale.ROOT,"%.2f",masteryLevel)+"; actividad de dificultad "+a.difficulty()+"; prerrequisitos dominados.")).toList();return new Recommendation(step,recs);}
	public EvaluationStart start(UUID student,UUID subject,UUID stepId){checkStudent(student);var path=paths.active(student,subject).orElseThrow(()->new ResourceNotFoundException("Active path was not found"));var step=path.steps().stream().filter(s->s.id().equals(stepId)).findFirst().orElseThrow(()->new ResourceNotFoundException("Path step was not found"));if(step.state()==PathStep.State.BLOQUEADO)throw new DiagnosticConflictException("A blocked path step cannot be evaluated");var existing=evaluations.inProgress(student,stepId);if(existing.isPresent())return new EvaluationStart(existing.get(),activities.findShortEvaluationByConcept(step.conceptId()));var assessmentItems=activities.findShortEvaluationByConcept(step.conceptId());if(assessmentItems.isEmpty())throw new InvalidPracticeRequestException("No active short-evaluation activities exist for this concept");if(step.state()!=PathStep.State.EN_PROGRESO){var updated=path.steps().stream().map(s->s.id().equals(stepId)?s.transitionTo(PathStep.State.EN_PROGRESO):s).toList();path=paths.update(path.withSteps(updated));step=path.steps().stream().filter(s->s.id().equals(stepId)).findFirst().orElseThrow();}var concept=concepts.findById(step.conceptId()).orElseThrow();var session=evaluations.save(new ShortEvaluation(null,student,subject,concept.id(),stepId,evaluations.nextAttempt(student,concept.id()),"EN_PROGRESO",null,null,null));return new EvaluationStart(session,assessmentItems);}
	public EvaluationAnswer answer(UUID student,UUID sessionId,UUID activityId,UUID optionId,String text,Integer seconds){checkStudent(student);var session=owned(student,sessionId);if(!"EN_PROGRESO".equals(session.state()))throw new DiagnosticConflictException("Evaluation is not in progress");if(evaluations.answers(sessionId).stream().anyMatch(a->a.activityId().equals(activityId)))throw new DiagnosticConflictException("Activity was already answered in this session");if(seconds!=null&&seconds<0)throw new InvalidPracticeRequestException("Seconds must not be negative");var activity=activities.findById(activityId).orElseThrow(()->new ResourceNotFoundException("Activity was not found"));if(!activity.active()||activity.usage()!=Activity.Usage.EVALUACION_CORTA||!activity.conceptId().equals(session.conceptId()))throw new InvalidPracticeRequestException("Activity must be active and belong to this short evaluation concept");boolean correctAnswer;try{if(activity.type()==Activity.Type.SELECCION_MULTIPLE){if(optionId==null||text!=null)throw new IllegalArgumentException("Select exactly one option");correctAnswer=correction.correctChoice(activity,optionId);}else{if(optionId!=null)throw new IllegalArgumentException("Short answer cannot include an option");correction.validateAnswer(text);correctAnswer=correction.correctShortAnswer(activity,text);}}catch(IllegalArgumentException e){throw new InvalidPracticeRequestException(e.getMessage());}return evaluations.saveAnswer(sessionId,activityId,optionId,text,correctAnswer,seconds);}
	public EvaluationResult finish(UUID student,UUID sessionId){checkStudent(student);var session=owned(student,sessionId);if(!"EN_PROGRESO".equals(session.state()))throw new DiagnosticConflictException("Evaluation is not in progress");var answers=evaluations.answers(sessionId);if(answers.isEmpty())throw new InvalidPracticeRequestException("Cannot finish an evaluation without answers");double score=100d*answers.stream().filter(EvaluationAnswer::correct).count()/answers.size();boolean passed=score>=approvalThreshold;var profileId=diagnostics.ensureProfile(student,session.subjectId());var previous=diagnostics.mastery(profileId,session.conceptId()).orElse(null);var evidence=answers.stream().map(a->{var activity=activities.findById(a.activityId()).orElseThrow();return new DiagnosticEvidence(activity.difficulty(),a.correct());}).toList();var updatedMastery=mastery.incorporate(session.conceptId(),previous,evidence);diagnostics.saveMastery(profileId,updatedMastery);diagnostics.saveHistory(profileId,session.conceptId(),previous==null?0:previous.level(),updatedMastery.level(),MasteryChangeSource.EVALUACION_CORTA,session.id());var completed=evaluations.save(new ShortEvaluation(session.id(),student,session.subjectId(),session.conceptId(),session.pathStepId(),session.attempt(),"COMPLETADA",Instant.now(clock),score,passed));var path=paths.active(student,session.subjectId()).orElseThrow();var edges=prerequisites.findBySubjectId(session.subjectId());var updatedSteps=generator.afterResult(path.steps(),session.conceptId(),passed,edges);var domains=new HashMap<UUID,Double>();diagnostics.profile(student,session.subjectId()).masteries().forEach(m->domains.put(m.conceptId(),m.level()));domains.put(updatedMastery.conceptId(),updatedMastery.level());updatedSteps=generator.unlockEligible(updatedSteps,edges,domains,initialThreshold);var updatedPath=paths.update(path.withSteps(updatedSteps));if(passed)reviewDeck.addMissingProgress(student,session.conceptId(),reviewDeck.activeCards(session.conceptId()),Instant.now(clock).plusSeconds(initialReviewDelayDays * 86400L));boolean recalculated=false;if(!passed&&evaluations.consecutiveFailures(student,session.pathStepId())>=failuresBeforeRecalculation){var replacement=recalculate(student,session.subjectId());recalculated=replacement.version()>updatedPath.version();}var state=updatedPath.steps().stream().filter(s->s.conceptId().equals(session.conceptId())).map(PathStep::state).findFirst().orElse(PathStep.State.REFUERZO);return new EvaluationResult(completed,state,recalculated);}
	public LearningPath recalculate(UUID student,UUID subject){checkStudent(student);var active=paths.active(student,subject).orElseThrow(()->new ResourceNotFoundException("Active path was not found"));var profile=diagnostics.profile(student,subject);var next=buildSteps(student,subject,profile,active);if(same(active.steps(),next))return active;paths.update(active.recalculate());var created=paths.save(new LearningPath(null,student,subject,active.version()+1,LearningPath.State.ACTIVA,List.of()));paths.saveSteps(created.id(),next);return paths.byId(created.id()).orElseThrow();}
	public boolean reopenAfterReview(UUID student,UUID subject,UUID conceptId){checkStudent(student);var current=paths.active(student,subject).or(()->paths.latest(student,subject)).orElseThrow(()->new ResourceNotFoundException("Learning path was not found"));var target=current.steps().stream().filter(s->s.conceptId().equals(conceptId)).findFirst().orElseThrow(()->new ResourceNotFoundException("Concept is not on the current path"));if(target.state()==PathStep.State.REFUERZO)return false;if(target.state()!=PathStep.State.DOMINADO)return false;var profile=diagnostics.profile(student,subject);var domains=new HashMap<UUID,Double>();profile.masteries().forEach(m->domains.put(m.conceptId(),m.level()));var next=generator.reopenAfterReview(concepts.findBySubjectId(subject),prerequisites.findBySubjectId(subject),domains,initialThreshold,current.steps(),conceptId);var old=current.recalculate();paths.update(old);var created=paths.save(new LearningPath(null,student,subject,current.version()+1,LearningPath.State.ACTIVA,List.of()));paths.saveSteps(created.id(),next);return true;}
	private LearningPath createPath(UUID student,UUID subject,KnowledgeProfile profile,LearningPath previous){var steps=buildSteps(student,subject,profile,previous);var latest=paths.latest(student,subject);int version=latest.map(p->p.version()+1).orElse(1);var created=paths.save(new LearningPath(null,student,subject,version,steps.stream().allMatch(s->s.state()==PathStep.State.DOMINADO)?LearningPath.State.COMPLETADA:LearningPath.State.ACTIVA,List.of()));paths.saveSteps(created.id(),steps);return paths.byId(created.id()).orElseThrow();}
	private List<PathStep> buildSteps(UUID student,UUID subject,KnowledgeProfile profile,LearningPath previous){var domains=new HashMap<UUID,Double>();profile.masteries().forEach(m->domains.put(m.conceptId(),m.level()));var graph=prerequisites.findBySubjectId(subject);var items=concepts.findBySubjectId(subject);return previous==null?generator.generate(items,graph,domains,initialThreshold):generator.regenerate(items,graph,domains,initialThreshold,previous.steps());}
	private boolean same(List<PathStep>a,List<PathStep>b){return a.size()==b.size()&&java.util.stream.IntStream.range(0,a.size()).allMatch(i->a.get(i).conceptId().equals(b.get(i).conceptId())&&a.get(i).state()==b.get(i).state());}
	private ShortEvaluation owned(UUID student,UUID id){var session=evaluations.find(id).orElseThrow(()->new ResourceNotFoundException("Evaluation was not found"));if(!session.studentId().equals(student))throw new DiagnosticConflictException("Evaluation belongs to another student");return session;}
	private void checkStudent(UUID student){if(!students.exists(student))throw new ResourceNotFoundException("Student was not found");}
}
